// Client-side search over search.json (generated by Jekyll), using MiniSearch.
(function () {
  'use strict';

  var script = document.currentScript;
  var indexUrl = script.getAttribute('data-index');
  var form = document.getElementById('search-page-form');
  var input = document.getElementById('search-page-input');
  var status = document.getElementById('search-status');
  var list = document.getElementById('search-results');
  var MAX_RESULTS = 50;
  var SNIPPET_RADIUS = 90;
  var miniSearch = null;

  // Lower case and strip accents, so "distribue" finds "Distribué".
  function normalize(term) {
    return term.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  }

  function escapeHtml(text) {
    return text.replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  function escapeRegExp(text) {
    return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  function highlight(text, terms) {
    if (!terms.length) return escapeHtml(text);
    var re = new RegExp('(' + terms.map(escapeRegExp).join('|') + ')', 'gi');
    return text.split(re).map(function (part, i) {
      return i % 2 ? '<mark>' + escapeHtml(part) + '</mark>' : escapeHtml(part);
    }).join('');
  }

  // Extract around the first matched term, or the beginning of the post.
  function snippet(content, terms) {
    var lower = content.toLowerCase();
    var pos = -1;
    terms.forEach(function (t) {
      var p = lower.indexOf(t.toLowerCase());
      if (p !== -1 && (pos === -1 || p < pos)) pos = p;
    });
    var start = Math.max(0, pos - SNIPPET_RADIUS);
    var end = Math.min(content.length, (pos === -1 ? 0 : pos) + SNIPPET_RADIUS * 2);
    return (start > 0 ? '… ' : '') + content.slice(start, end) + (end < content.length ? ' …' : '');
  }

  function render(query) {
    list.innerHTML = '';
    if (!query) {
      status.textContent = '';
      return;
    }
    var results = miniSearch.search(query);
    status.textContent = results.length
      ? results.length + ' post' + (results.length > 1 ? 's' : '') + ' found for “' + query + '”' +
        (results.length > MAX_RESULTS ? ' (first ' + MAX_RESULTS + ' shown)' : '')
      : 'No post found for “' + query + '”';

    results.slice(0, MAX_RESULTS).forEach(function (r) {
      var li = document.createElement('li');
      li.innerHTML =
        '<span class="post-date">' + escapeHtml(r.date) + '</span> ' +
        '<a class="post-link" href="' + escapeHtml(r.url) + '">' + highlight(r.title, r.terms) + '</a>' +
        '<br><small>' + highlight(snippet(r.content, r.terms), r.terms) + '</small>' +
        (r.tags ? '<br><small>tags: <em>' + highlight(r.tags, r.terms) + '</em></small>' : '');
      list.appendChild(li);
    });
  }

  function currentQuery() {
    return (new URLSearchParams(window.location.search).get('q') || '').trim();
  }

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    var query = input.value.trim();
    history.replaceState(null, '', query ? '?q=' + encodeURIComponent(query) : window.location.pathname);
    if (miniSearch) render(query);
  });

  input.value = currentQuery();
  status.textContent = 'Loading the search index…';

  fetch(indexUrl)
    .then(function (response) {
      if (!response.ok) throw new Error(response.status);
      return response.json();
    })
    .then(function (posts) {
      miniSearch = new MiniSearch({
        fields: ['title', 'tags', 'content'],
        storeFields: ['title', 'url', 'date', 'tags', 'content'],
        processTerm: normalize,
        searchOptions: {
          boost: { title: 3, tags: 2 },
          prefix: true,
          fuzzy: 0.2,
          combineWith: 'AND'
        }
      });
      miniSearch.addAll(posts);
      render(currentQuery());
    })
    .catch(function () {
      status.textContent = 'The search index could not be loaded.';
    });
})();
